int main(void) {
	/* 1. Bật clock GPIOC và cấu hình PC13 (Output Push-Pull 2 MHz) */
	SET_BIT(RCC_APB2ENR, 4);
	GPIOC_CRH &= ~(0xFU << 20);
	GPIOC_CRH |= (0x2U << 20);

	/* 2. Bật clock GPIOA và cấu hình PA8 (AF Push-Pull 50 MHz cho MCO) */
	SET_BIT(RCC_APB2ENR, 2);
	GPIOA_CRH &= ~(0xFU << 0);
	GPIOA_CRH |= (0xBU << 0);
	GPIOA_CRL &= ~(0xFU << 0);
	GPIOA_CRL |= (0x8U << 0); /* CNF = 10, MODE = 00 */
	SET_BIT(GPIOA_ODR, 0); /* ghi 1 vào ODR bit 0 = chọn PULL-UP */

	/* 3. Bật HSE (8 MHz) và đợi ổn định */
	SET_BIT(RCC_CR, 16);
	while (!(RCC_CR & (1U << 17))) {
	}

	/* 4. Cấu hình Flash: 2 wait states (cho 72 MHz) và bật Prefetch buffer */
	FLASH_ACR &= ~(0x7U << 0);
	FLASH_ACR |= (0x2U << 0);
	SET_BIT(FLASH_ACR, 4);

	/* 5. Cấu hình PLL (HSE x 9 = 72 MHz) và APB1 chia 2 (36 MHz) */
	SET_BIT(RCC_CFGR, 16);        // PLLSRC = HSE
	RCC_CFGR &= ~(0xFU << 18);
	RCC_CFGR |= (0x7U << 18);     // PLLMUL = x9 (0b0111)
	RCC_CFGR &= ~(0x7U << 8);
	RCC_CFGR |= (0x4U << 8);      // PPRE1 = chia 2 (0b100)

	/* 6. Bật PLL và đợi khóa tần số */
	SET_BIT(RCC_CR, 24);
	while (!(RCC_CR & (1U << 25))) {
	}

	/* 7. Chuyển SYSCLK sang PLL và đợi xác nhận */
	RCC_CFGR &= ~(0x3U << 0);
	RCC_CFGR |= (0x2U << 0);
	while (((RCC_CFGR >> 2) & 0x3U) != 0x2U) {
	}

	/* 8. Cấu hình SysTick tạo ngắt cờ mỗi 1 ms tại 72 MHz */
	SYST_RVR = 72000 - 1;
	SYST_CVR = 0;
	SYST_CSR = 0x5;

	/* 9. Chọn nguồn xuất ra MCO (PA8): đặt 0x6U (HSE) đo trước, sau đó đổi sang 0x7U (PLL/2) */
	RCC_CFGR &= ~(0x7U << 24);
	RCC_CFGR |= (0x6U << 24); // Đặt Breakpoint tại dòng dưới hoặc đầu vòng for để chụp SFRs
	/*10. Nối PA0 với đường ngắt EXTI0*/
	SET_BIT(RCC_APB2ENR, 0); /* bật clock AFIO (bit 0) */
	AFIO_EXTICR1 &= ~(0xFU << 0); /* 0000 = chọn cổng A cho đường 0 */
	SET_BIT(EXTI_FTSR, 0); /* kích hoạt ở cạnh xuống */
	SET_BIT(EXTI_IMR, 0); /* cho phép ngắt đường 0 */
	SET_BIT(NVIC_ISER0, 6); /* bật ngắt trong NVIC: EXTI0 là IRQ số 6 */
	/* 11. Khởi tạo TIM2 tạo ngắt tràn mỗi 1 ms (xung Timer APB1 = 72 MHz) */
	SET_BIT(RCC_APB1ENR, 0); /* Bit 0 (TIM2EN): Bật clock cho TIM2 */
	TIM2_PSC = 72 - 1; /* Chia 72 -> 1 MHz (1 tick = 1 us) */
	TIM2_ARR = 1000 - 1; /* Đếm 1000 tick -> 1000 us = 1 ms */
	SET_BIT(TIM2_DIER, 0); /* Bit 0 (UIE): Cho phép ngắt Update Interrupt */
	SET_BIT(TIM2_CR1, 0); /* Bit 0 (CEN): Bắt đầu cho TIM2 đếm */
	/*TIM2 la IQR 28*/
	SET_BIT(NVIC_ISER0, 28);
	for (;;) {
	}
}

/* Khai báo biến đếm chống dội dùng chung giữa 2 ngắt -> bắt buộc có volatile */
static volatile uint32_t debounce_ms = 0;

void EXTI0_IRQHandler(void) {
	if (EXTI_PR & (1U << 0)) {
		/* 1. Xóa cờ pending EXTI0 (ghi 1 để xóa) */
		EXTI_PR = (1U << 0);

		/* 2. Chặn tạm thời ngắt đường 0 (chỉ xóa duy nhất bit 0) */
		EXTI_IMR &= ~(1U << 0);

		/* 3. Nạp thời gian chờ chống dội 20 ms cho TIM2 đếm ngược */
		debounce_ms = 20U;
	}
}

void TIM2_IRQHandler(void) {
	/* Kiểm tra cờ Update Interrupt Flag (UIF - bit 0) */
	if (TIM2_SR & (1U << 0)) {
		/* 1. Xóa cờ UIF để thoát ngắt */
		TIM2_SR = ~(1U << 0);

		/* 2. Xử lý đếm ngược chống dội phím */
		if (debounce_ms > 0U) {
			debounce_ms--;
			if (debounce_ms == 0U) {
				/* Kiểm tra nút nhấn PA0 vẫn đang ở mức thấp (0) */
				if (!(GPIOA_IDR & (1U << 0))) {
					GPIOC_ODR ^= (1U << 13); /* Đảo trạng thái LED PC13 */
				}

				/* Xóa cờ nhiễu phát sinh trong 20 ms vừa qua rồi bật lại ngắt EXTI0 */
				EXTI_PR = (1U << 0);
				EXTI_IMR |= (1U << 0);
			}
		}
	}
}
